2	// SPDX-License-Identifier: Apache-2.0
3	
4	use std::sync::Arc;
5	use std::time::Duration;
6	
7	use tokio::sync::mpsc;
8	use tokio_util::sync::CancellationToken;
9	
10	use dynamo_kv_router::indexer::LocalKvIndexer;
11	use dynamo_kv_router::protocols::*;
12	
13	use crate::kv_router::metrics::kv_publisher_metrics;
14	
15	use super::DEFAULT_MAX_BATCH_BLOCKS;
16	use super::batching::BatchingState;
17	use super::dedup::{EventDedupFilter, EventDedupPolicy};
18	use super::sinks::{RouterEventBatchSink, emit};
19	
20	pub(super) async fn run_event_processor_loop<P: RouterEventBatchSink + 'static>(
21	    publisher: P,
22	    worker_id: u64,
23	    cancellation_token: CancellationToken,
24	    mut rx: mpsc::UnboundedReceiver<Vec<PlacementEvent>>,
25	    local_indexer: Option<Arc<LocalKvIndexer>>,
26	    timeout_ms: Option<u64>,
27	    max_batch_blocks: usize,
28	) {
29	    let mut batching_state = BatchingState::new(max_batch_blocks);
30	    let mut dedup = EventDedupFilter::new();
31	    let mut last_raw_input_id: Option<u64> = None;
32	
33	    loop {
34	        tokio::select! {
35	            _ = cancellation_token.cancelled() => {
36	                tracing::info!("KV Event source received cancellation signal");
37	                let mut output = Vec::new();
38	                batching_state.flush(&local_indexer, worker_id, &mut dedup, &mut output).await;
39	                publish_output(&publisher, worker_id, &output).await;
40	                break;
41	            }
42	            event_batch = rx.recv() => {
43	                let Some(event_batch) = event_batch else {
44	                    tracing::debug!("Event processor channel closed.");
45	                    let mut output = Vec::new();
46	                    batching_state.flush(&local_indexer, worker_id, &mut dedup, &mut output).await;
47	                    publish_output(&publisher, worker_id, &output).await;
48	                    break;
49	                };
50	                let mut output = Vec::new();
51	
52	                // Process the complete source list before returning to `select!` so
53	                // another channel item, the timeout, or cancellation cannot split it.
54	                'event_batch: for placement_event in event_batch {
55	                    let raw_event_id = placement_event.event.event_id;
56	                    if let Some(last_id) = last_raw_input_id
57	                        && raw_event_id > last_id + 1
58	                    {
59	                        let gap = raw_event_id - last_id - 1;
60	                        tracing::warn!(
61	                            worker_id,
62	                            last_raw_input_id = last_id,
63	                            raw_event_id,
64	                            gap,
65	                            "Input event gap detected: raw events dropped before batching"
66	                        );
67	                        if let Some(metrics) = kv_publisher_metrics() {
68	                            metrics.increment_engines_dropped_events(gap);
69	                        } else {
70	                            tracing::warn!(
71	                                worker_id,
72	                                gap,
73	                                "Failed to record dropped events metric: metrics not initialized"
74	                            );
75	                        }
76	                    }
77	                    last_raw_input_id = Some(raw_event_id);
78	
79	                    let storage_tier = placement_event.placement.tier;
80	                    let residency_domain = placement_event.placement.residency_domain;
81	                    tracing::trace!(
82	                        "Event processor for worker_id {} processing event: {:?}",
83	                        worker_id,
84	                        placement_event.event.data
85	                    );
86	
87	                    match &placement_event.event.data {
88	                        KvCacheEventData::Removed(_) | KvCacheEventData::Stored(_) => {
89	                            batching_state
90	                                .push(
91	                                    placement_event,
92	                                    &local_indexer,
93	                                    worker_id,
94	                                    &mut dedup,
95	                                    &mut output,
96	                                )
97	                                .await;
98	                        }
99	                        KvCacheEventData::Cleared => {
100	                            batching_state.flush(&local_indexer, worker_id, &mut dedup, &mut output).await;
101	                            let event = placement_event.event;
102	                            dedup.clear_rank_domain(
103	                                event.dp_rank,
104	                                residency_domain,
105	                                EventDedupPolicy::RefCounted,
106	                            );
107	                            let applied = emit(
108	                                &local_indexer,
109	                                worker_id,
110	                                storage_tier,
111	                                residency_domain,
112	                                KvCacheEvent {
113	                                    event_id: batching_state.next_publish_id,
114	                                    data: KvCacheEventData::Cleared,
115	                                    dp_rank: event.dp_rank,
116	                                },
117	                                &mut output,
118	                            )
119	                            .await;
120	                            if !applied {
121	                                output.pop();
122	                                tracing::error!(
123	                                    worker_id,
124	                                    dp_rank = event.dp_rank,
125	                                    ?residency_domain,
126	                                    "Fencing KV event publisher after local reset failure"
127	                                );
128	                                // NOTE: This token owns the publisher's discovery and recovery
129	                                // advertisement too. Once the local reset barrier fails, withdrawing
130	                                // the complete source is the only safe way to avoid advertising a
131	                                // cursor whose local snapshot has diverged.
132	                                cancellation_token.cancel();
133	                                break 'event_batch;
134	                            }
135	                            batching_state.next_publish_id = batching_state
136	                                .next_publish_id
137	                                .checked_add(1)
138	                                .expect("KV event publisher outbound cursor exhausted");
139	                        }
140	                    }
141	                }
142	
143	                // Without a timeout, flush the compatible tail at the native-list
144	                // boundary. With a timeout, retain it for possible cross-list batching.
145	                if batching_state.has_pending()
146	                    && match timeout_ms {
147	                        None => true,
148	                        Some(ms) => batching_state.is_timeout_elapsed(ms),
149	                    }
150	                {
151	                    batching_state.flush(&local_indexer, worker_id, &mut dedup, &mut output).await;
152	                }
153	                publish_output(&publisher, worker_id, &output).await;
154	            }
155	            _ = tokio::time::sleep(
156	                timeout_ms
157	                    .map(|ms| batching_state.remaining_timeout(ms))
158	                    .unwrap_or(Duration::from_secs(3600))
159	            ), if timeout_ms.is_some() && batching_state.has_pending() => {
160	                let mut output = Vec::new();
161	                batching_state.flush(&local_indexer, worker_id, &mut dedup, &mut output).await;
162	                publish_output(&publisher, worker_id, &output).await;
163	            }
164	        }
165	    }
166	}
167	
168	async fn publish_output<P: RouterEventBatchSink>(
169	    publisher: &P,
170	    worker_id: u64,
171	    output: &[RouterEvent],
172	) {
173	    if output.is_empty() {
174	        return;
175	    }
176	    if let Err(e) = publisher.publish_events(output).await {
177	        tracing::error!(
178	            worker_id,
179	            attempted_event_count = output.len(),
180	            error = %e,
181	            "One or more KV event publishes failed"
182	        );
183	    }
184	}
185	
186	pub(super) async fn start_event_processor<P: RouterEventBatchSink + 'static>(
187	    publisher: P,
188	    worker_id: u64,
189	    cancellation_token: CancellationToken,
190	    rx: mpsc::UnboundedReceiver<Vec<PlacementEvent>>,
191	    local_indexer: Option<Arc<LocalKvIndexer>>,
192	    batching_timeout_ms: Option<u64>,
193	) {
194	    run_event_processor_loop(
195	        publisher,
196	        worker_id,
197	        cancellation_token,
198	        rx,
199	        local_indexer,
200	        batching_timeout_ms,
201	        DEFAULT_MAX_BATCH_BLOCKS,
202	    )
203	    .await
204	}
