1	// SPDX-FileCopyrightText: Copyright (c) 2024-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
2	// SPDX-License-Identifier: Apache-2.0
3	
4	use std::sync::Arc;
5	use std::time::{Duration, Instant};
6	
7	use dynamo_kv_router::indexer::LocalKvIndexer;
8	use dynamo_kv_router::protocols::{KvCacheEventData, Placement, PlacementEvent, RouterEvent};
9	
10	use super::dedup::{EventDedupFilter, EventDedupPolicy};
11	use super::sinks::emit;
12	
13	/// Pure accumulator for adjacent compatible placement mutations.
14	///
15	/// The caller-provided key carries the exact logical owner/source and physical
16	/// tier. The coalescer adds DP-rank, operation, and Store-chain boundaries. It
17	/// deliberately owns no event IDs, timers, indexers, publishers, or error
18	/// policy, so both publisher lifecycles can share it without sharing commits.
19	#[derive(Debug)]
20	pub(super) struct PlacementEventCoalescer<K> {
21	    pending: Option<(K, PlacementEvent)>,
22	    max_batch_blocks: usize,
23	}
24	
25	impl<K: Eq> PlacementEventCoalescer<K> {
26	    pub(super) fn new(max_batch_blocks: usize) -> Self {
27	        Self {
28	            pending: None,
29	            max_batch_blocks,
30	        }
31	    }
32	
33	    pub(super) fn has_pending(&self) -> bool {
34	        self.pending.is_some()
35	    }
36	
37	    /// Push one input and return up to two ready outputs in stream order.
38	    ///
39	    /// Two outputs are possible when an incompatible or oversized mutation
40	    /// follows a pending mutation, or when `Cleared` flushes the pending value
41	    /// and then passes through as its own barrier.
42	    pub(super) fn push(&mut self, key: K, event: PlacementEvent) -> [Option<PlacementEvent>; 2] {
43	        if matches!(&event.event.data, KvCacheEventData::Cleared) {
44	            return [self.flush(), Some(event)];
45	        }
46	
47	        let can_merge = self.pending.as_ref().is_some_and(|(pending_key, pending)| {
48	            pending_key == &key
49	                && pending.event.dp_rank == event.event.dp_rank
50	                && compatible_data(&pending.event.data, &event.event.data)
51	        });
52	        if can_merge {
53	            let pending = &mut self
54	                .pending
55	                .as_mut()
56	                .expect("merge compatibility requires one pending event")
57	                .1;
58	            merge_data(&mut pending.event.data, event.event.data);
59	            if event_block_count(pending) >= self.max_batch_blocks {
60	                return [self.flush(), None];
61	            }
62	            return [None, None];
63	        }
64	
65	        let flushed = self.flush();
66	        if event_block_count(&event) >= self.max_batch_blocks {
67	            return [flushed, Some(event)];
68	        }
69	        self.pending = Some((key, event));
70	        [flushed, None]
71	    }
72	
73	    pub(super) fn flush(&mut self) -> Option<PlacementEvent> {
74	        self.pending.take().map(|(_, event)| event)
75	    }
76	}
77	
78	fn merge_data(pending: &mut KvCacheEventData, next: KvCacheEventData) {
79	    match (pending, next) {
80	        (KvCacheEventData::Stored(pending), KvCacheEventData::Stored(next)) => {
81	            pending.blocks.extend(next.blocks);
82	        }
83	        (KvCacheEventData::Removed(pending), KvCacheEventData::Removed(next)) => {
84	            pending.block_hashes.extend(next.block_hashes);
85	        }
86	        _ => unreachable!("merge compatibility requires matching mutation kinds"),
87	    }
88	}
89	
90	fn compatible_data(pending: &KvCacheEventData, next: &KvCacheEventData) -> bool {
91	    match (pending, next) {
92	        (KvCacheEventData::Stored(pending), KvCacheEventData::Stored(next)) => {
93	            next.parent_hash == pending.blocks.last().map(|block| block.block_hash)
94	        }
95	        (KvCacheEventData::Removed(_), KvCacheEventData::Removed(_)) => true,
96	        _ => false,
97	    }
98	}
99	
100	fn event_block_count(event: &PlacementEvent) -> usize {
101	    match &event.event.data {
102	        KvCacheEventData::Stored(data) => data.blocks.len(),
103	        KvCacheEventData::Removed(data) => data.block_hashes.len(),
104	        KvCacheEventData::Cleared => 0,
105	    }
106	}
107	
108	/// Accumulator for in-flight KV cache events that will be merged into a single
109	/// [`RouterEvent`] before being forwarded to the event sink.
110	#[derive(Debug)]
111	pub(super) struct BatchingState {
112	    coalescer: PlacementEventCoalescer<Placement>,
113	    pub(super) next_publish_id: u64,
114	    pub(super) last_flush_time: Instant,
115	}
116	
117	impl BatchingState {
118	    pub(super) fn new(max_batch_blocks: usize) -> Self {
119	        Self {
120	            coalescer: PlacementEventCoalescer::new(max_batch_blocks),
121	            next_publish_id: 1,
122	            last_flush_time: Instant::now(),
123	        }
124	    }
125	
126	    pub(super) fn has_pending(&self) -> bool {
127	        self.coalescer.has_pending()
128	    }
129	
130	    pub(super) fn record_flush_time(&mut self) {
131	        self.last_flush_time = Instant::now();
132	    }
133	
134	    pub(super) fn remaining_timeout(&self, timeout_ms: u64) -> Duration {
135	        let timeout = Duration::from_millis(timeout_ms);
136	        let elapsed = self.last_flush_time.elapsed();
137	        if elapsed >= timeout {
138	            Duration::ZERO
139	        } else {
140	            timeout - elapsed
141	        }
142	    }
143	
144	    pub(super) fn is_timeout_elapsed(&self, timeout_ms: u64) -> bool {
145	        self.remaining_timeout(timeout_ms) == Duration::ZERO
146	    }
147	
148	    pub(super) async fn flush(
149	        &mut self,
150	        local_indexer: &Option<Arc<LocalKvIndexer>>,
151	        worker_id: u64,
152	        dedup: &mut EventDedupFilter,
153	        output: &mut Vec<RouterEvent>,
154	    ) {
155	        if let Some(event) = self.coalescer.flush() {
156	            self.emit_ready(event, local_indexer, worker_id, dedup, output)
157	                .await;
158	        }
159	        self.record_flush_time();
160	    }
161	
162	    pub(super) async fn push(
163	        &mut self,
164	        event: PlacementEvent,
165	        local_indexer: &Option<Arc<LocalKvIndexer>>,
166	        worker_id: u64,
167	        dedup: &mut EventDedupFilter,
168	        output: &mut Vec<RouterEvent>,
169	    ) {
170	        let key = event.placement.clone();
171	        let ready = self.coalescer.push(key, event);
172	        let flushed = ready.iter().any(Option::is_some);
173	        for ready in ready.into_iter().flatten() {
174	            self.emit_ready(ready, local_indexer, worker_id, dedup, output)
175	                .await;
176	        }
177	        if flushed {
178	            self.record_flush_time();
179	        }
180	    }
181	
182	    async fn emit_ready(
183	        &mut self,
184	        placement_event: PlacementEvent,
185	        local_indexer: &Option<Arc<LocalKvIndexer>>,
186	        worker_id: u64,
187	        dedup: &mut EventDedupFilter,
188	        output: &mut Vec<RouterEvent>,
189	    ) {
190	        let tier = placement_event.placement.tier;
191	        let domain = placement_event.placement.residency_domain;
192	        let mut event = placement_event.event;
193	        event.data = match event.data {
194	            KvCacheEventData::Removed(data) => {
195	                let Some(filtered) = dedup.filter_remove_in_domain(
196	                    event.dp_rank,
197	                    tier,
198	                    domain,
199	                    EventDedupPolicy::RefCounted,
200	                    data,
201	                ) else {
202	                    return;
203	                };
204	                KvCacheEventData::Removed(filtered)
205	            }
206	            KvCacheEventData::Stored(data) => {
207	                dedup.track_store_in_domain(
208	                    event.dp_rank,
209	                    tier,
210	                    domain,
211	                    EventDedupPolicy::RefCounted,
212	                    &data,
213	                );
214	                KvCacheEventData::Stored(data)
215	            }
216	            KvCacheEventData::Cleared => {
217	                unreachable!("Cleared is handled by the publisher's barrier policy")
218	            }
219	        };
220	        event.event_id = self.next_publish_id;
221	        let _ = emit(local_indexer, worker_id, tier, domain, event, output).await;
222	        self.next_publish_id = self
223	            .next_publish_id
224	            .checked_add(1)
225	            .expect("KV event publisher outbound cursor exhausted");
226	    }
227	}
228	
229	#[cfg(test)]
230	mod tests {
231	    use dynamo_kv_router::protocols::{
232	        ExternalSequenceBlockHash, KvCacheEvent, KvCacheRemoveData, KvCacheStoreData,
233	        KvCacheStoredBlockData, LocalBlockHash, Placement, ResidencyDomain, StorageTier,
234	    };
235	
236	    use super::*;
237	
