122	        worker_id: WorkerId,
123	        kv_block_size: u32,
124	        source_config: KvEventSourceConfig,
125	        cancellation_token: CancellationToken,
126	        tx: mpsc::UnboundedSender<Vec<PlacementEvent>>,
127	        next_event_id: Arc<AtomicU64>,
128	    ) -> Result<Self> {
129	        match source_config {
130	            KvEventSourceConfig::Zmq {
131	                endpoint,
132	                topic,
133	                image_token_id,
134	            } => {
135	                let listener_handle =
136	                    component
137	                        .drt()
138	                        .runtime()
139	                        .secondary()
140	                        .spawn(start_zmq_listener(
141	                            endpoint.clone(),
142	                            topic.clone(),
143	                            worker_id,
144	                            tx,
145	                            cancellation_token.clone(),
146	                            kv_block_size,
147	                            next_event_id,
148	                            image_token_id,
149	                        ));
150	                let listener_abort_handle = listener_handle.abort_handle();
151	                let supervisor_handle =
152	                    component
153	                        .drt()
154	                        .runtime()
155	                        .secondary()
156	                        .spawn(supervise_zmq_listener(
157	                            listener_handle,
158	                            endpoint,
159	                            topic,
160	                            cancellation_token,
161	                        ));
162	
163	                Ok(KvEventSource::Zmq {
164	                    listener_abort_handle,
165	                    supervisor_handle,
166	                })
167	            }
168	        }
169	    }
170	
171	    fn shutdown(&self) {
172	        match self {
173	            KvEventSource::Zmq {
174	                listener_abort_handle,
175	                supervisor_handle,
176	            } => {
177	                listener_abort_handle.abort();
178	                supervisor_handle.abort();
179	            }
180	        }
181	    }
182	}
183	
184	/// A publisher of KV events.
185	///
186	/// The engine-side publisher lifetime is coupled to this Dynamo publisher and its advertised
187	/// publisher ID. Restarting the engine publisher independently while this value survives is not
188	/// supported. Future independent restart support must either emit an ordered rank-scoped
189	/// `Cleared` event before the new stream or create a new Dynamo publisher ID.
190	pub struct KvEventPublisher {
191	    /// The size of the KV block.
192	    kv_block_size: u32,
193	    /// The source of KV events.
194	    /// Can be `None` if all events are provided through
195	    /// [`KvEventPublisher::publish`] or [`KvEventPublisher::publish_batch`].
196	    source: Option<KvEventSource>,
197	    /// The cancellation token.
198	    cancellation_token: CancellationToken,
199	    /// The ID of the local worker emitting placement events.
200	    worker_id: WorkerId,
201	    /// The channel to send events to.
202	    tx: mpsc::UnboundedSender<Vec<PlacementEvent>>,
203	    /// Internal monotonic event ID counter. Shared with the ZMQ listener if present.
204	    next_event_id: Arc<AtomicU64>,
205	}
206	
207	impl KvEventPublisher {
208	    pub fn new(
209	        endpoint: Endpoint,
210	        kv_block_size: u32,
211	        source_config: Option<KvEventSourceConfig>,
212	    ) -> Result<Self> {
213	        Self::new_with_local_indexer(
214	            endpoint,
215	            kv_block_size,
216	            source_config,
217	            false,
218	            0,
219	            DEFAULT_BATCHING_TIMEOUT_MS,
220	        )
221	    }
222	
223	    pub fn new_with_local_indexer(
224	        endpoint: Endpoint,
225	        kv_block_size: u32,
226	        source_config: Option<KvEventSourceConfig>,
227	        enable_local_indexer: bool,
228	        dp_rank: DpRank,
229	        batching_timeout_ms: Option<u64>,
230	    ) -> Result<Self> {
231	        let kv_state_endpoint = endpoint.id();
232	        Self::new_with_local_indexer_at(
233	            endpoint,
234	            kv_state_endpoint,
235	            kv_block_size,
236	            source_config,
237	            enable_local_indexer,
238	            dp_rank,
239	            batching_timeout_ms,
240	        )
241	    }
242	
243	    pub fn new_with_local_indexer_at(
244	        endpoint: Endpoint,
245	        kv_state_endpoint: EndpointId,
246	        kv_block_size: u32,
247	        source_config: Option<KvEventSourceConfig>,
248	        enable_local_indexer: bool,
249	        dp_rank: DpRank,
250	        batching_timeout_ms: Option<u64>,
251	    ) -> Result<Self> {
252	        Self::new_with_local_indexer_and_worker_id_at(
253	            endpoint,
254	            kv_state_endpoint,
255	            None,
256	            kv_block_size,
257	            source_config,
258	            enable_local_indexer,
259	            dp_rank,
260	            batching_timeout_ms,
261	        )
262	    }
263	
264	    pub fn new_with_local_indexer_and_worker_id(
265	        endpoint: Endpoint,
266	        worker_id: Option<WorkerId>,
267	        kv_block_size: u32,
268	        source_config: Option<KvEventSourceConfig>,
269	        enable_local_indexer: bool,
270	        dp_rank: DpRank,
271	        batching_timeout_ms: Option<u64>,
272	    ) -> Result<Self> {
273	        let kv_state_endpoint = endpoint.id();
274	        Self::new_with_local_indexer_and_worker_id_at(
275	            endpoint,
276	            kv_state_endpoint,
277	            worker_id,
278	            kv_block_size,
279	            source_config,
280	            enable_local_indexer,
281	            dp_rank,
282	            batching_timeout_ms,
283	        )
284	    }
285	
286	    #[allow(clippy::too_many_arguments)]
287	    pub fn new_with_local_indexer_and_worker_id_at(
288	        endpoint: Endpoint,
289	        kv_state_endpoint: EndpointId,
290	        worker_id: Option<WorkerId>,
291	        kv_block_size: u32,
292	        source_config: Option<KvEventSourceConfig>,
293	        enable_local_indexer: bool,
294	        dp_rank: DpRank,
295	        batching_timeout_ms: Option<u64>,
296	    ) -> Result<Self> {
297	        let component = endpoint.component().clone();
298	        let cancellation_token = CancellationToken::new();
299	        let batching_timeout_ms = batching_timeout_ms
300	            .filter(|&ms| {
301	                if ms > MAX_BATCHING_TIMEOUT_MS {
302	                    tracing::warn!(
303	                        requested_ms = ms,
304	                        max_ms = MAX_BATCHING_TIMEOUT_MS,
305	                        "batching_timeout_ms too high, capping to 15s"
306	                    );
307	                }
308	                ms > 0
309	            })
310	            .map(|ms| ms.min(MAX_BATCHING_TIMEOUT_MS));
311	
312	        let (tx, rx) = mpsc::unbounded_channel::<Vec<PlacementEvent>>();
313	        let worker_id = worker_id.unwrap_or_else(|| component.drt().connection_id());
314	
315	        let _ = KvPublisherMetrics::from_component(&component);
316	
317	        let endpoint_id = endpoint.id();
318	        tracing::info!(
319	            %kv_state_endpoint,
320	            "Initializing KvEventPublisher for worker {worker_id} on serving endpoint {endpoint_id}"
321	        );
322	
323	        if enable_local_indexer {
324	            tracing::info!(
325	                "LocalKvIndexer enabled for worker {worker_id} on endpoint {endpoint_id}"
326	            );
327	        }
328	
329	        let next_event_id = Arc::new(AtomicU64::new(0));
330	
331	        let mut source = None;
332	        if let Some(config) = source_config {
333	            source = Some(KvEventSource::start(
334	                component.clone(),
335	                worker_id,
336	                kv_block_size,
337	                config,
338	                cancellation_token.clone(),
339	                tx.clone(),
340	                next_event_id.clone(),
341	            )?);
342	        }
343	
344	        let local_indexer = if enable_local_indexer {
345	            let metrics = Arc::new(KvIndexerMetrics::new_unregistered());
346	            Some(Arc::new(LocalKvIndexer::new(
347	                cancellation_token.clone(),
348	                kv_block_size,
349	                metrics,
350	                WORKER_KV_INDEXER_BUFFER_SIZE,
351	            )))
352	        } else {
353	            None
354	        };
355	
356	        let cancellation_token_clone = cancellation_token.clone();
357	        let local_indexer_clone = local_indexer.clone();
358	
359	        tracing::info!("Using event plane for KV event publishing");
360	        let endpoint_clone = endpoint.clone();
361	        component.drt().runtime().secondary().spawn(async move {
362	            let event_publisher =
363	                match dynamo_runtime::transports::event_plane::EventPublisher::for_endpoint_id(
364	                    endpoint_clone.drt(),
365	                    &kv_state_endpoint,
366	                    KV_EVENT_SUBJECT,
367	                )
368	                .await
369	                {
370	                    Ok(publisher) => publisher,
371	                    Err(e) => {
372	                        tracing::error!("Failed to create event publisher: {}", e);
373	                        return;
374	                    }
375	                };
376	            let publisher_id = event_publisher.publisher_id();
377	
378	            let recovery_endpoint = if let Some(local_indexer) = local_indexer_clone.as_ref() {
379	                match start_worker_kv_query_endpoint(
380	                    component.clone(),
381	                    publisher_id,
382	                    worker_id,
383	                    dp_rank,
384	                    local_indexer.clone(),
385	                )
386	                .await
387	                {
388	                    Ok(endpoint) => Some(endpoint),
389	                    Err(error) => {
390	                        tracing::error!(
391	                            %error,
392	                            worker_id,
393	                            dp_rank,
394	                            publisher_id,
395	                            "KV recovery endpoint failed; advertising a live-only KV source"
396	                        );
397	                        None
398	                    }
399	                }
400	            } else {
401	                None
402	            };
403	
404	            if cancellation_token_clone.is_cancelled() {
405	                if let Some(endpoint) = recovery_endpoint {
406	                    let _ = endpoint.shutdown().await;
407	                }
408	                return;
409	            }
410	
411	            let source = DiscoveredKvEventSource {
412	                kv_state_endpoint: kv_state_endpoint.clone(),
413	                worker: WorkerWithDpRank::new(worker_id, dp_rank),
414	                publisher_id,
415	                recovery_target: recovery_endpoint
416	                    .as_ref()
417	                    .map(|endpoint| endpoint.instance().clone()),
418	            };
419	            let source_spec = DiscoverySpec::EventSource {
420	                scope: EventScope::Endpoint {
421	                    endpoint: kv_state_endpoint.clone(),
422	                },
423	                topic: KV_EVENT_SUBJECT.to_string(),
424	                publisher_id,
425	                metadata: match serde_json::to_value(&source) {
426	                    Ok(metadata) => metadata,
427	                    Err(error) => {
428	                        tracing::error!(%error, "Failed to encode KV event source advertisement");
429	                        if let Some(endpoint) = recovery_endpoint {
430	                            let _ = endpoint.shutdown().await;
431	                        }
432	                        return;
433	                    }
434	                },
435	            };
436	            let source_instance = match component.drt().discovery().register(source_spec).await {
437	                Ok(instance) => instance,
438	                Err(error) => {
439	                    tracing::error!(%error, "Failed to advertise KV event source");
440	                    if let Some(endpoint) = recovery_endpoint {
441	                        let _ = endpoint.shutdown().await;
442	                    }
443	                    return;
444	                }
445	            };
446	
447	            start_event_processor(
448	                EventPlanePublisher(event_publisher),
449	                worker_id,
450	                cancellation_token_clone,
451	                rx,
452	                local_indexer_clone,
453	                batching_timeout_ms,
454	            )
455	            .await;
456	
457	            if let Err(error) = component
458	                .drt()
459	                .discovery()
460	                .unregister(source_instance)
461	                .await
462	            {
463	                tracing::warn!(%error, publisher_id, "Failed to unregister KV event source");
464	            }
465	            if let Some(endpoint) = recovery_endpoint
466	                && let Err(error) = endpoint.shutdown().await
467	            {
468	                tracing::warn!(%error, publisher_id, "Failed to stop KV recovery endpoint");
469	            }
470	        });
471	
472	        Ok(Self {
473	            kv_block_size,
474	            source,
475	            cancellation_token,
476	            worker_id,
477	            tx,
478	            next_event_id,
479	        })
480	    }
481	
482	    pub fn publish(&self, event: KvCacheEvent) -> Result<(), mpsc::error::SendError<KvCacheEvent>> {
483	        self.send_singleton(PlacementEvent::local_gpu(self.worker_id, event))
484	    }
485	
486	    /// Publish an ordered list of engine events as one processor input.
487	    ///
488	    /// The processor handles the complete list without receiving another list
489	    /// or servicing its batching timer between source events. Existing
490	    /// coalescing and block-count limits still apply within the list. Empty
491	    /// lists are ignored.
492	    pub fn publish_batch(
493	        &self,
494	        events: Vec<KvCacheEvent>,
495	    ) -> Result<(), mpsc::error::SendError<Vec<KvCacheEvent>>> {
496	        if events.is_empty() {
497	            return Ok(());
498	        }
499	
500	        let placement_events = events
501	            .into_iter()
502	            .map(|event| PlacementEvent::local_gpu(self.worker_id, event))
503	            .collect();
504	        self.tx.send(placement_events).map_err(|err| {
505	            mpsc::error::SendError(err.0.into_iter().map(|event| event.event).collect())
506	        })
507	    }
508	
509	    pub fn publish_with_storage_tier(
510	        &self,
511	        event: KvCacheEvent,
512	        storage_tier: StorageTier,
513	    ) -> Result<(), mpsc::error::SendError<KvCacheEvent>> {
514	        let placement_event = PlacementEvent::new(
515	            Placement::local_worker(self.worker_id, event.dp_rank, storage_tier),
516	            event,
517	        );
518	        self.send_singleton(placement_event)
519	    }
520	
521	    /// Publishes events that share one source visibility boundary.
522	    pub fn publish_batch_with_storage_tiers(
523	        &self,
524	        events: Vec<(KvCacheEvent, StorageTier)>,
525	    ) -> Result<(), mpsc::error::SendError<Vec<KvCacheEvent>>> {
526	        if events.is_empty() {
527	            return Ok(());
528	        }
529	
530	        let events = events
531	            .into_iter()
532	            .map(|(event, storage_tier)| {
533	                PlacementEvent::new(
534	                    Placement::local_worker(self.worker_id, event.dp_rank, storage_tier),
535	                    event,
536	                )
537	            })
538	            .collect();
539	
540	        self.tx.send(events).map_err(|err| {
541	            mpsc::error::SendError(err.0.into_iter().map(|event| event.event).collect())
542	        })
543	    }
544	
545	    fn send_singleton(
546	        &self,
547	        event: PlacementEvent,
548	    ) -> Result<(), mpsc::error::SendError<KvCacheEvent>> {
549	        self.tx.send(vec![event]).map_err(|err| {
550	            mpsc::error::SendError(
551	                err.0
552	                    .into_iter()
553	                    .next()
554	                    .expect("singleton publish returned an empty failed batch")
555	                    .event,
556	            )
557	        })
558	    }
559	
560	    pub fn next_event_id(&self) -> u64 {
561	        self.next_event_id.fetch_add(1, Ordering::SeqCst)
562	    }
563	
564	    pub fn kv_block_size(&self) -> u32 {
565	        self.kv_block_size
566	    }
567	
568	    pub fn shutdown(&mut self) {
569	        if !self.cancellation_token.is_cancelled() {
570	            self.cancellation_token.cancel();
571	        }
572	
573	        if let Some(source) = self.source.take() {
574	            source.shutdown();
575	        }
576	    }
577	}
578	
579	impl Drop for KvEventPublisher {
580	    fn drop(&mut self) {
581	        self.shutdown();
582	    }
583	}
