53	    group_metadata: FxHashMap<(DpRank, u32), KvCacheGroupMetadata>,
54	    cache_namespaces: FxHashMap<(WorkerWithDpRank, u64), CacheNamespaceState>,
55	}
56	
57	#[derive(Debug, Clone, PartialEq, Eq)]
