129	    pub fn preprocess(&mut self, raw: RawKvEvent, worker: WorkerWithDpRank) -> Option<RawKvEvent> {
130	        self.preprocess_with_reason(raw, worker).ok()
131	    }
132	
133	    pub fn preprocess_with_reason(
134	        &mut self,
135	        raw: RawKvEvent,
136	        worker: WorkerWithDpRank,
137	    ) -> Result<RawKvEvent, ZmqEventFilterReason> {
138	        match raw.ownership() {
139	            Ok(KvEventOwnership::Framework) => {}
140	            Ok(KvEventOwnership::Kvcr) => {
141	                return Err(ZmqEventFilterReason::UnsupportedOwnership);
142	            }
143	            Err(_) => return Err(ZmqEventFilterReason::UnknownOwnership),
144	        }
145	        self.preprocess_residency_with_reason(raw, worker)
146	    }
147	
148	    /// Normalize a version-gated state-agent stream which may contain both
149	    /// framework and vLLM-enriched KVCR transitions.
150	    pub fn preprocess_residency_with_reason(
151	        &mut self,
152	        mut raw: RawKvEvent,
153	        worker: WorkerWithDpRank,
154	    ) -> Result<RawKvEvent, ZmqEventFilterReason> {
155	        if raw.ownership().is_err() {
156	            return Err(ZmqEventFilterReason::UnknownOwnership);
157	        }
158	        if raw.is_ignored() {
159	            return Err(ZmqEventFilterReason::IgnoredEvent);
160	        }
161	
162	        // Non-local events are dropped by policy (no shared-index consumer yet).
163	        // Classify them here, before the lower-tier bypass, so the gate covers
164	        // every tier (including Disk/External). Otherwise the listener would
165	        // accept the event, burn a next_event_id, and only drop it in
166	        // conversion, leaving an id gap the event processor mistakes for an
167	        // engine drop (engines_dropped_events).
168	        if matches!(raw.locality(), Some(Locality::Remote | Locality::Unknown)) {
169	            return Err(ZmqEventFilterReason::NonLocalLocality);
170	        }
171	
172	        // Classify by medium before touching normalizer state:
173	        //  - Device / HostPinned (GPU, CPU offload #10368) stay on the normalizer
174	        //    path so their salted namespaces still propagate.
175	        //  - Disk / External (STORAGE) are hash-only lower-tier events with no
176	        //    extra_keys/cache_namespace, so they must not mutate per-group
177	        //    metadata or the salted-namespace chain and are outside the SW/SSM
178	        //    group filter's semantics; bypass straight to conversion, which keeps
179	        //    them (no event id is wasted).
180	        //  - Unrecognized media (e.g. vLLM 0.26.0 FS/OBJ) fail closed here so the
181	        //    listener records an intentional filter. Bypassing to conversion,
182	        //    which drops them, would instead accept the event, burn a
183	        //    next_event_id, and leave an id gap the event processor mistakes for
184	        //    an engine drop -- the same trap the locality gate above avoids.
185	        if let Some(m) = raw.medium() {
186	            match StorageTier::from_kv_medium(m) {
187	                Some(StorageTier::Device | StorageTier::HostPinned) => {}
188	                Some(_) => return Ok(raw),
189	                None => return Err(ZmqEventFilterReason::UnknownMedium),
190	            }
191	        }
192	
193	        let metadata = raw.metadata();
194	        if matches!(raw, RawKvEvent::BlockStored { .. }) {
195	            self.learn_metadata(metadata, worker.dp_rank);
196	        }
197	        if let Some(reason) = self.filter_reason(metadata, worker.dp_rank) {
198	            return Err(reason);
199	        }
200	        self.propagate_cache_namespace(&mut raw, worker)?;
201	        Ok(raw)
202	    }
