204	    pub fn normalize_preprocessed(
205	        &self,
206	        raw: RawKvEvent,
207	        event_id: u64,
208	        worker: WorkerWithDpRank,
209	    ) -> Option<PlacementEvent> {
210	        convert_event(
211	            raw,
212	            event_id,
213	            self.kv_block_size,
214	            worker,
215	            &self.warning_count,
216	            self.image_token_id,
217	        )
