223	        event_id: u64,
224	        worker: WorkerWithDpRank,
225	    ) -> Option<PlacementEvent> {
226	        let raw = self.preprocess(raw, worker)?;
227	        self.normalize_preprocessed(raw, event_id, worker)
228	    }
