230	    fn learn_metadata(&mut self, metadata: KvCacheEventMetadata, dp_rank: DpRank) {
231	        let (Some(group_idx), Some(kind)) = (metadata.group_idx, metadata.kv_cache_spec_kind)
232	        else {
233	            return;
234	        };
235	
236	        self.group_metadata.insert(
237	            (dp_rank, group_idx),
238	            KvCacheGroupMetadata {
239	                kind,
240	                sliding_window: metadata.kv_cache_spec_sliding_window,
241	            },
242	        );
243	    }
244	
245	    fn propagate_cache_namespace(
246	        &mut self,
247	        raw: &mut RawKvEvent,
248	        worker: WorkerWithDpRank,
249	    ) -> Result<(), ZmqEventFilterReason> {
250	        match raw {
251	            RawKvEvent::BlockStored {
252	                block_hashes,
253	                parent_block_hash,
254	                cache_namespace,
255	                ..
256	            } => {
257	                if cache_namespace.as_deref() == Some("") {
258	                    *cache_namespace = None;
259	                }
260	                let namespace = if let Some(namespace) = cache_namespace.as_deref() {
261	                    parent_block_hash
262	                        .as_ref()
263	                        .and_then(|parent| {
264	                            self.cache_namespaces.get(&(worker, (*parent).into_u64()))
265	                        })
266	                        .and_then(|state| match state {
267	                            CacheNamespaceState::Namespaced(parent_namespace)
268	                                if parent_namespace.as_ref() == namespace =>
269	                            {
270	                                Some(Arc::clone(parent_namespace))
271	                            }
272	                            _ => None,
273	                        })
274	                        .or_else(|| Some(Arc::from(namespace)))
275	                } else if let Some(parent) = parent_block_hash.as_ref() {
276	                    match self.cache_namespaces.get(&(worker, (*parent).into_u64())) {
277	                        Some(CacheNamespaceState::Namespaced(namespace)) => {
278	                            *cache_namespace = Some(namespace.to_string());
279	                            Some(Arc::clone(namespace))
280	                        }
281	                        Some(CacheNamespaceState::Ambiguous) => {
282	                            return Err(ZmqEventFilterReason::AmbiguousCacheNamespace);
283	                        }
284	                        None => {
285	                            // Deliberately preserve the unsalted interpretation when a
286	                            // listener joins in the middle of a chain. The vLLM wire
287	                            // format cannot distinguish an unknown salted parent from a
288	                            // genuinely unsalted one, and retaining every unsalted block
289	                            // here would duplicate the index on the event hot path. The
290	                            // backend still enforces its own cache isolation; this narrow
291	                            // fail-open case can only pollute the router overlap score.
292	                            None
293	                        }
294	                    }
295	                } else {
296	                    None
297	                };
298	
299	                if let Some(namespace) = namespace {
300	                    let state = CacheNamespaceState::Namespaced(namespace);
301	                    for block_hash in block_hashes.iter() {
302	                        self.cache_namespaces
303	                            .entry((worker, (*block_hash).into_u64()))
304	                            .and_modify(|existing| {
305	                                if *existing != state {
306	                                    *existing = CacheNamespaceState::Ambiguous;
307	                                }
308	                            })
309	                            .or_insert_with(|| state.clone());
310	                    }
311	                } else {
312	                    // Do not retain every unsalted block. If this hash already
313	                    // belongs to a namespace, however, fail closed on future
314	                    // propagation because the external hash is now ambiguous.
315	                    for block_hash in block_hashes.iter() {
316	                        if let Some(existing) = self
317	                            .cache_namespaces
318	                            .get_mut(&(worker, (*block_hash).into_u64()))
319	                        {
320	                            *existing = CacheNamespaceState::Ambiguous;
321	                        }
322	                    }
323	                }
324	            }
325	            RawKvEvent::BlockRemoved { block_hashes, .. } => {
326	                for block_hash in block_hashes.iter() {
327	                    let key = (worker, (*block_hash).into_u64());
328	                    if !matches!(
329	                        self.cache_namespaces.get(&key),
330	                        Some(CacheNamespaceState::Ambiguous)
331	                    ) {
332	                        self.cache_namespaces.remove(&key);
333	                    }
334	                }
335	            }
336	            RawKvEvent::AllBlocksCleared { .. } => {
337	                self.cache_namespaces
338	                    .retain(|(known_worker, _), _| *known_worker != worker);
339	            }
340	            RawKvEvent::Ignored => {}
341	        }
342	        Ok(())
343	    }
344	
345	    fn filter_reason(
346	        &self,
347	        metadata: KvCacheEventMetadata,
348	        dp_rank: DpRank,
349	    ) -> Option<ZmqEventFilterReason> {
350	        if let Some(kind) = metadata.kv_cache_spec_kind {
351	            if kind.is_main_attention() {
352	                return None;
353	            }
354	            if kind == KvCacheSpecKind::Unknown {
355	                return Some(ZmqEventFilterReason::UnknownKind);
356	            }
357	            return Some(ZmqEventFilterReason::NonMainAttentionKind);
358	        }
359	
360	        let group_idx = metadata.group_idx?;
361	
362	        if let Some(metadata) = self.group_metadata.get(&(dp_rank, group_idx)) {
363	            let _sliding_window = metadata.sliding_window;
364	            if metadata.kind.is_main_attention() {
365	                return None;
366	            }
367	            if metadata.kind == KvCacheSpecKind::Unknown {
368	                return Some(ZmqEventFilterReason::UnknownKind);
369	            }
370	            return Some(ZmqEventFilterReason::NonMainAttentionGroup);
371	        }
372	
373	        if group_idx == 0 {
374	            None
375	        } else {
376	            Some(ZmqEventFilterReason::UnlearnedGroupIdx)
377	        }
378	    }
379	}
