17	/// Trait for publishing KV cache events.
18	/// This abstracts the runtime dependency so mocker components can remain generic.
19	pub trait KvCacheEventSink: Send + Sync {
20	    fn publish(&self, event: KvCacheEvent) -> anyhow::Result<()>;
21	
22	    fn publish_with_storage_tier(
23	        &self,
24	        event: KvCacheEvent,
25	        _storage_tier: StorageTier,
26	    ) -> anyhow::Result<()> {
27	        self.publish(event)
28	    }
29	
30	    /// Publishes events that share one source visibility boundary.
31	    ///
32	    /// Implementations that do not have a native batch representation retain
33	    /// singleton delivery semantics by default.
34	    fn publish_batch_with_storage_tiers(
35	        &self,
36	        events: Vec<(KvCacheEvent, StorageTier)>,
37	    ) -> anyhow::Result<()> {
38	        let mut first_error = None;
39	        for (event, storage_tier) in events {
40	            if let Err(error) = self.publish_with_storage_tier(event, storage_tier) {
41	                first_error.get_or_insert(error);
42	            }
43	        }
44	        first_error.map_or(Ok(()), Err)
45	    }
46	}
