4	//! ZMQ KV event publishing in the vLLM native wire format.
5	
6	use std::collections::VecDeque;
7	use std::sync::Arc;
8	use std::time::{SystemTime, UNIX_EPOCH};
9	
10	use anyhow::Result;
11	use bytes::Bytes;
12	use dynamo_kv_router::protocols::{KvCacheEvent, KvCacheEventData, StorageTier};
13	use futures::{Sink, SinkExt, StreamExt};
14	use serde::Serialize;
15	use tmq::{
16	    Context, Multipart, SocketBuilder,
17	    publish::{Publish, publish},
18	    router::{Router, router},
19	};
20	use tokio::sync::{Mutex, mpsc};
21	
22	use crate::common::protocols::{RawKvEvent, RawKvEventSink};
