27	const ZMQ_SNDTIMEOUT_MS: i32 = 0;
28	const ZMQ_RCVTIMEOUT_MS: i32 = 100;
29	const ZMQ_RECONNECT_IVL_MS: i32 = 100;
30	const ZMQ_RECONNECT_IVL_MAX_MS: i32 = 5000;
31	const ZMQ_TCP_KEEPALIVE: i32 = 1;
32	const ZMQ_LINGER_MS: i32 = 0;
33	
34	/// Maximum number of entries in the replay ring buffer.
35	const REPLAY_BUFFER_CAPACITY: usize = 10_000;
36	
37	#[derive(Serialize)]
38	#[serde(tag = "type")]
39	enum ZmqRawKvEvent {
40	    BlockStored {
41	        block_hashes: Vec<u64>,
42	        parent_block_hash: Option<u64>,
43	        token_ids: Vec<u32>,
44	        block_size: u32,
45	        #[serde(skip_serializing_if = "Option::is_none")]
46	        medium: Option<&'static str>,
47	        group_idx: u32,
48	    },
49	    BlockRemoved {
50	        block_hashes: Vec<u64>,
51	        #[serde(skip_serializing_if = "Option::is_none")]
52	        medium: Option<&'static str>,
