57	pub struct ZmqKvEventSink {
58	    tx: mpsc::UnboundedSender<Vec<RawKvEvent>>,
59	}
60	
61	impl ZmqKvEventSink {
62	    pub async fn new(
63	        port: u16,
64	        replay_port: Option<u16>,
65	        dp_rank: u32,
66	        block_size: u32,
67	    ) -> Result<Self> {
68	        let (tx, mut rx) = mpsc::unbounded_channel::<Vec<RawKvEvent>>();
69	
70	        let endpoint = format!("tcp://0.0.0.0:{port}");
71	        let pub_socket = bind_pub_socket(&endpoint)
72	            .await
73	            .map_err(|e| anyhow::anyhow!("ZMQ PUB bind to {endpoint} failed: {e}"))?;
74	        tracing::info!("ZmqKvEventSink bound to {endpoint} for dp_rank {dp_rank}");
75	
76	        let mut router_socket = if let Some(rp) = replay_port {
77	            let replay_ep = format!("tcp://0.0.0.0:{rp}");
78	            let sock = bind_router_socket(&replay_ep)
79	                .await
80	                .map_err(|e| anyhow::anyhow!("ZMQ ROUTER bind to {replay_ep} failed: {e}"))?;
81	            tracing::info!(
82	                "ZmqKvEventSink replay ROUTER bound to {replay_ep} for dp_rank {dp_rank}"
83	            );
84	            Some(sock)
85	        } else {
86	            None
87	        };
88	
89	        tokio::spawn(async move {
90	            let mut seq_num: u64 = 0;
91	            let mut ring_buffer: VecDeque<(u64, Bytes)> = VecDeque::new();
92	
93	            loop {
94	                tokio::select! {
95	                    biased;
96	
97	                    replay_result = async {
98	                        match router_socket.as_mut() {
99	                            Some(socket) => socket.next().await,
100	                            None => std::future::pending().await,
101	                        }
102	                    } => {
103	                        let req_msg = match replay_result {
104	                            Some(Ok(req_msg)) => multipart_message(req_msg),
105	                            Some(Err(error)) => {
106	                                tracing::warn!("Replay ROUTER recv error: {error}");
107	                                router_socket = None;
108	                                continue;
109	                            }
110	                            None => {
111	                                tracing::warn!("Replay ROUTER stream ended");
112	                                router_socket = None;
113	                                continue;
114	                            }
115	                        };
116	                        if req_msg.len() < 3 {
117	                            tracing::warn!("Unexpected replay request frame count: {}", req_msg.len());
118	                            continue;
119	                        }
120	
121	                        let identity = Bytes::copy_from_slice(req_msg.first().unwrap());
122	                        let start_seq_bytes = req_msg.get(2).unwrap();
123	                        if start_seq_bytes.len() != 8 {
124	                            tracing::warn!("Invalid replay start_seq length: {}", start_seq_bytes.len());
125	                            continue;
126	                        }
127	                        let start_seq = u64::from_be_bytes(start_seq_bytes[..8].try_into().unwrap());
128	
129	                        tracing::debug!(dp_rank, start_seq, buffer_len = ring_buffer.len(), "Replay request received");
130	
131	                        let buffer_first = ring_buffer.front().map(|(seq, _)| *seq);
132	                        let buffer_last = ring_buffer.back().map(|(seq, _)| *seq);
133	                        let outside_buffer = match (buffer_first, buffer_last) {
134	                            (Some(first), Some(last)) => start_seq < first || start_seq > last,
135	                            _ => true,
136	                        };
137	                        if outside_buffer {
138	                            let buffer_first_display = buffer_first
139	                                .map(|seq| seq.to_string())
140	                                .unwrap_or_else(|| "empty".to_string());
141	                            let buffer_last_display = buffer_last
142	                                .map(|seq| seq.to_string())
143	                                .unwrap_or_else(|| "empty".to_string());
144	                            tracing::warn!(
145	                                dp_rank,
146	                                start_seq,
147	                                buffer_first = ?buffer_first,
148	                                buffer_last = ?buffer_last,
149	                                buffer_len = ring_buffer.len(),
150	                                "Replay request outside buffer: start_seq={start_seq}, buffer=[{},{}]",
151	                                buffer_first_display,
152	                                buffer_last_display,
153	                            );
154	                        }
155	
156	                        let start_idx = ring_buffer.front()
157	                            .map(|(first_seq, _)| start_seq.saturating_sub(*first_seq) as usize)
158	                            .unwrap_or(0)
159	                            .min(ring_buffer.len());
160	
161	                        let sock = router_socket.as_mut().unwrap();
162	                        for (seq, payload) in ring_buffer.iter().skip(start_idx) {
163	                            // ROUTER consumes the identity frame; the DEALER-side
164	                            // listener receives [delimiter, topic, seq, payload].
165	                            let frames = vec![
166	                                identity.clone().to_vec(),
167	                                Vec::new(),
168	                                Vec::new(),
169	                                seq.to_be_bytes().to_vec(),
170	                                payload.to_vec(),
171	                            ];
172	                            if let Err(e) = send_multipart_direct(sock, frames).await {
173	                                tracing::warn!("Replay send error: {e}");
174	                                break;
175	                            }
176	                        }
177	
178	                        let sentinel_frames = vec![
179	                            identity.to_vec(),
180	                            Vec::new(),
181	                            Vec::new(),
182	                            (-1i64).to_be_bytes().to_vec(),
183	                            Vec::new(),
184	                        ];
185	                        let _ = send_multipart_direct(sock, sentinel_frames).await;
186	                    }
187	
188	                    msg_opt = rx.recv() => {
189	                        let Some(raw_events) = msg_opt else { break };
190	
191	                        let payload = match encode_event_batch(&raw_events, block_size, dp_rank) {
192	                            Ok(Some(payload)) => payload,
193	                            Ok(None) => continue,
194	                            Err(e) => {
195	                                tracing::warn!("Failed to serialize ZMQ KV event batch: {e}");
196	                                continue;
197	                            }
198	                        };
199	
200	                        if router_socket.is_some() {
201	                            if ring_buffer.len() >= REPLAY_BUFFER_CAPACITY {
202	                                ring_buffer.pop_front();
203	                            }
204	                            ring_buffer.push_back((seq_num, payload.clone()));
205	                        }
206	
207	                        let frames = vec![
208	                            Vec::new(),
209	                            seq_num.to_be_bytes().to_vec(),
210	                            payload.to_vec(),
211	                        ];
212	                        if let Err(e) = send_multipart(&pub_socket, frames).await {
213	                            tracing::warn!("Failed to send ZMQ KV event: {e}");
214	                        }
215	
216	                        seq_num += 1;
217	                    }
218	                }
219	            }
220	        });
221	
222	        Ok(Self { tx })
223	    }
