225	    fn enqueue(&self, events: Vec<RawKvEvent>) -> anyhow::Result<()> {
226	        if events.is_empty() {
227	            return Ok(());
228	        }
229	        self.tx
230	            .send(events)
231	            .map_err(|_| anyhow::anyhow!("ZMQ event sink channel closed"))
232	    }
233	}
234	
235	impl RawKvEventSink for ZmqKvEventSink {
236	    fn publish(&self, event: RawKvEvent) -> anyhow::Result<()> {
237	        self.enqueue(vec![event])
238	    }
239	
240	    fn publish_batch(&self, events: Vec<RawKvEvent>) -> anyhow::Result<()> {
241	        self.enqueue(events)
242	    }
243	}
244	
245	pub(crate) fn encode_event_batch(
246	    raw_events: &[RawKvEvent],
247	    block_size: u32,
248	    dp_rank: u32,
249	) -> std::result::Result<Option<Bytes>, rmp_serde::encode::Error> {
250	    let events = raw_events
251	        .iter()
252	        .flat_map(|event| {
253	            convert_to_zmq_events(
254	                &event.event,
255	                event.block_token_ids.as_deref(),
256	                block_size,
257	                event.storage_tier,
258	            )
259	        })
260	        .collect::<Vec<_>>();
261	    if events.is_empty() {
262	        return Ok(None);
263	    }
264	
265	    let timestamp = SystemTime::now()
266	        .duration_since(UNIX_EPOCH)
267	        .unwrap_or_default()
268	        .as_secs_f64();
269	    let batch: (f64, Vec<ZmqRawKvEvent>, Option<i32>) = (timestamp, events, Some(dp_rank as i32));
270	    rmp_serde::to_vec_named(&batch).map(|payload| Some(payload.into()))
271	}
272	
273	fn convert_to_zmq_events(
274	    event: &KvCacheEvent,
275	    block_token_ids: Option<&[Vec<u32>]>,
276	    block_size: u32,
277	    storage_tier: StorageTier,
278	) -> Vec<ZmqRawKvEvent> {
279	    let medium = storage_tier.to_kv_medium();
280	    match &event.data {
281	        KvCacheEventData::Stored(store_data) => {
282	            let block_hashes: Vec<u64> = store_data.blocks.iter().map(|b| b.block_hash.0).collect();
283	            let parent_block_hash = store_data.parent_hash.map(|h| h.0);
284	
285	            let token_ids: Vec<u32> = block_token_ids
286	                .map(|tids| tids.iter().flatten().copied().collect())
287	                .unwrap_or_default();
288	
289	            assert_eq!(
290	                token_ids.len(),
