106	impl KvPublisherMetrics {
107	    /// Create from a Component, memoized in a static OnceLock.
108	    /// Uses the MetricsHierarchy API which auto-prepends `dynamo_component_`,
109	    /// injects hierarchy labels (including `worker_id`), and registers with the
110	    /// DRT `MetricsRegistry`.
111	    pub fn from_component(component: &Component) -> Arc<Self> {
112	        KV_PUBLISHER_METRICS
113	            .get_or_init(|| Arc::new(Self::build(component)))
