117	    /// Register the publisher's metrics against any metrics hierarchy.
118	    ///
119	    /// Split out of [`Self::from_component`] so registration is reachable from
120	    /// tests: `from_component` needs a real `Component` (and therefore a live
121	    /// `DistributedRuntime`) and memoizes into a process-global `OnceLock`, so
122	    /// only the first call in a process runs this code at all.
123	    fn build<H: MetricsHierarchy>(hierarchy: &H) -> Self {
124	        let metrics = hierarchy.metrics();
125	        let engines_dropped_events_total = metrics
126	            .create_intcounter(
127	                kv_publisher::ENGINES_DROPPED_EVENTS_TOTAL,
128	                "Total number of raw events dropped by engines before reaching publisher (detected via event_id gaps)",
129	                &[],
130	            )
131	            .expect("failed to create kv_publisher_engines_dropped_events_total");
132	        let zmq_events_total = metrics
133	            .create_intcountervec(
134	                kv_publisher::ZMQ_EVENTS_TOTAL,
135	                "Total number of ZMQ KV events seen by the relay",
136	                &["stage", "event_type"],
137	                &[],
138	            )
139	            .expect("failed to create kv_publisher_zmq_events_total");
140	        let zmq_filtered_events_total = metrics
141	            .create_intcountervec(
142	                kv_publisher::ZMQ_FILTERED_EVENTS_TOTAL,
143	                "Total number of ZMQ KV events filtered before conversion",
144	                &["event_type", "reason"],
145	                &[],
146	            )
147	            .expect("failed to create kv_publisher_zmq_filtered_events_total");
148	        let zmq_conversion_issues_total = metrics
149	            .create_intcountervec(
150	                kv_publisher::ZMQ_CONVERSION_ISSUES_TOTAL,
151	                "Total number of ZMQ KV events dropped due to conversion issues",
152	                &["event_type", "reason"],
153	                &[],
154	            )
155	            .expect("failed to create kv_publisher_zmq_conversion_issues_total");
156	        let zmq_suspicious_events_total = metrics
157	            .create_intcountervec(
158	                kv_publisher::ZMQ_SUSPICIOUS_EVENTS_TOTAL,
159	                "Total number of suspicious-but-forwarded ZMQ KV events",
160	                &["event_type", "reason"],
161	                &[],
162	            )
163	            .expect("failed to create kv_publisher_zmq_suspicious_events_total");
164	
165	        Self {
166	            engines_dropped_events_total,
167	            zmq_events_total,
168	            zmq_filtered_events_total,
169	            zmq_conversion_issues_total,
170	            zmq_suspicious_events_total,
171	        }
172	    }
173	
174	    /// Increment the engines dropped events counter by the given amount.
175	    pub fn increment_engines_dropped_events(&self, count: u64) {
176	        self.engines_dropped_events_total.inc_by(count);
177	    }
178	
179	    pub fn increment_zmq_event(&self, stage: &'static str, event_type: &'static str) {
180	        self.zmq_events_total
181	            .with_label_values(&[stage, event_type])
182	            .inc();
183	    }
184	
185	    pub fn increment_zmq_filtered_event(&self, event_type: &'static str, reason: &'static str) {
186	        self.zmq_filtered_events_total
187	            .with_label_values(&[event_type, reason])
188	            .inc();
189	    }
190	
191	    pub fn increment_zmq_conversion_issue(&self, event_type: &'static str, reason: &'static str) {
192	        self.zmq_conversion_issues_total
193	            .with_label_values(&[event_type, reason])
194	            .inc();
195	    }
196	
197	    pub fn increment_zmq_suspicious_event(&self, event_type: &'static str, reason: &'static str) {
198	        self.zmq_suspicious_events_total
199	            .with_label_values(&[event_type, reason])
200	            .inc();
201	    }
202	}
