654	/// Per-request routing phase latency histograms (milliseconds).
655	pub struct RoutingOverheadMetrics {
656	    pub block_hashing: prometheus::Histogram,
657	    pub indexer_find_matches: prometheus::Histogram,
658	    pub seq_hashing: prometheus::Histogram,
659	    pub scheduling: prometheus::Histogram,
