667	impl RoutingOverheadMetrics {
668	    /// Register routing overhead histograms with the given registry and store for later use.
669	    /// Metric names: `dynamo_router_overhead_*` with const label `router_id=instance_id`.
670	    /// Called during frontend HTTP service setup (`service_v2.rs`), so these metrics
671	    /// are served on the frontend's own port (default 8000). Not available in the
672	    /// standalone router, which has no frontend HTTP server.
673	    pub fn register(
674	        registry: &prometheus::Registry,
675	        instance_id: u64,
676	    ) -> Result<(), prometheus::Error> {
677	        let m = ROUTING_OVERHEAD_METRICS.get_or_init(|| {
678	            let compute_buckets = compute_overhead_buckets();
679	            let async_buckets = async_overhead_buckets();
680	            let router_id = instance_id.to_string();
681	            let make = |suffix: &str, help: &str, buckets: Vec<f64>| {
682	                let name = format!("{}_{}", name_prefix::ROUTER, suffix);
683	                prometheus::Histogram::with_opts(
684	                    HistogramOpts::new(name, help)
685	                        .const_label(labels::ROUTER_ID, &router_id)
686	                        .buckets(buckets),
687	                )
688	            };
689	            let block_hashing = make(
690	                routing_overhead::BLOCK_HASHING_MS,
691	                "Time spent computing block hashes in milliseconds",
692	                compute_buckets.clone(),
693	            )
694	            .expect("overhead_block_hashing_ms");
695	            let indexer_find_matches = make(
696	                routing_overhead::INDEXER_FIND_MATCHES_MS,
697	                "Time spent in indexer find_matches in milliseconds",
698	                async_buckets.clone(),
699	            )
700	            .expect("overhead_indexer_find_matches_ms");
701	            let seq_hashing = make(
702	                routing_overhead::SEQ_HASHING_MS,
703	                "Time spent computing sequence hashes in milliseconds",
704	                compute_buckets,
705	            )
706	            .expect("overhead_seq_hashing_ms");
707	            let scheduling = make(
708	                routing_overhead::SCHEDULING_MS,
709	                "Time spent in scheduler worker selection in milliseconds",
710	                async_buckets.clone(),
711	            )
712	            .expect("overhead_scheduling_ms");
713	            let total = make(
714	                routing_overhead::TOTAL_MS,
715	                "Total routing overhead per request in milliseconds",
716	                async_buckets.clone(),
717	            )
718	            .expect("overhead_total_ms");
719	            let shared_cache_query = make(
720	                routing_overhead::SHARED_CACHE_QUERY_MS,
721	                "Time spent querying the shared KV cache in milliseconds",
722	                async_buckets,
723	            )
724	            .expect("overhead_shared_cache_query_ms");
725	            let shared_cache_errors_total = {
726	                let name = format!(
727	                    "{}_{}",
728	                    name_prefix::ROUTER,
729	                    routing_overhead::SHARED_CACHE_ERRORS_TOTAL
730	                );
731	                prometheus::IntCounter::with_opts(
732	                    Opts::new(name, "Total shared cache failures")
733	                        .const_label(labels::ROUTER_ID, &router_id),
734	                )
735	                .expect("shared_cache_errors_total")
736	            };
737	            Arc::new(Self {
738	                block_hashing,
739	                indexer_find_matches,
740	                seq_hashing,
741	                scheduling,
742	                total,
743	                shared_cache_query,
744	                shared_cache_errors_total,
745	            })
746	        });
747	        registry.register(Box::new(m.block_hashing.clone()))?;
748	        registry.register(Box::new(m.indexer_find_matches.clone()))?;
749	        registry.register(Box::new(m.seq_hashing.clone()))?;
750	        registry.register(Box::new(m.scheduling.clone()))?;
751	        registry.register(Box::new(m.total.clone()))?;
752	        registry.register(Box::new(m.shared_cache_query.clone()))?;
753	        registry.register(Box::new(m.shared_cache_errors_total.clone()))?;
754	        Ok(())
755	    }
756	
757	    /// Returns the registered metrics if `register()` was called earlier.
758	    pub fn get() -> Option<Arc<Self>> {
759	        ROUTING_OVERHEAD_METRICS.get().cloned()
760	    }
761	
762	    /// Observe routing overhead timings in milliseconds.
763	    ///
764	    /// `indexer_duration` and `shared_cache_duration` are independent wall-clock times
765	    /// measured inside the `tokio::join!` block. They run in parallel, so
766	    /// `find_matches_elapsed >= max(indexer_duration, shared_cache_duration)`.
767	    pub fn observe(
768	        &self,
769	        hash_elapsed: Duration,
770	        seq_hash_elapsed: Duration,
771	        indexer_duration: Duration,
772	        shared_cache_duration: Option<Duration>,
773	        find_matches_elapsed: Duration,
774	        total_elapsed: Duration,
775	    ) {
776	        self.block_hashing
777	            .observe(hash_elapsed.as_secs_f64() * 1000.0);
778	        self.seq_hashing
779	            .observe(seq_hash_elapsed.saturating_sub(hash_elapsed).as_secs_f64() * 1000.0);
780	        self.indexer_find_matches
781	            .observe(indexer_duration.as_secs_f64() * 1000.0);
782	        if let Some(sc_duration) = shared_cache_duration {
783	            self.shared_cache_query
784	                .observe(sc_duration.as_secs_f64() * 1000.0);
785	        }
786	        self.scheduling.observe(
787	            total_elapsed
788	                .saturating_sub(find_matches_elapsed)
789	                .as_secs_f64()
790	                * 1000.0,
791	        );
792	        self.total.observe(total_elapsed.as_secs_f64() * 1000.0);
793	    }
794	
795	    /// Increment the shared cache error counter.
796	    pub fn inc_shared_cache_errors(&self) {
797	        self.shared_cache_errors_total.inc();
798	    }
799	}
