840	    pub kv_hit_rate: prometheus::Histogram,
841	    pub kv_transfer_estimated_latency_seconds: prometheus::Histogram,
842	    pub shared_cache_hit_rate: prometheus::Histogram,
843	    pub shared_cache_beyond_blocks: prometheus::Histogram,
844	    pub non_max_overlap_selections_total: IntCounterVec,
845	    pub overlap_blocks_lost: HistogramVec,
846	}
