1119	    pub(crate) fn set_policies(&self, configured: &str, effective: &str) {
1120	        for policy in ["ttl", "lru", "disabled"] {
1121	            self.configured_policy
1122	                .with_label_values(&[policy])
1123	                .set(i64::from(policy == configured));
