1130	    pub(crate) fn observe(&self, current: ApproximateLruStats, previous: &mut ApproximateLruStats) {
1131	        let gauge = |value: usize| i64::try_from(value).unwrap_or(i64::MAX);
1132	        self.ranks
1133	            .with_label_values(&["lru"])
1134	            .set(gauge(current.ranks));
1135	        self.ranks
1136	            .with_label_values(&["ttl_fallback"])
1137	            .set(gauge(current.fallback_ranks));
1138	        for (state, value) in [
1139	            ("resident", current.resident_blocks),
1140	            ("active", current.active_blocks),
1141	            ("inactive", current.inactive_blocks),
1142	            ("private", current.private_blocks),
1143	            ("overcapacity", current.overcapacity_blocks),
1144	        ] {
1145	            self.blocks.with_label_values(&[state]).set(gauge(value));
1146	        }
1147	        self.leases.set(gauge(current.leases));
1148	        self.mutation_queue_depth
1149	            .set(gauge(current.mutation_queue_depth));
1150	
1151	        self.fallback_activations_total.inc_by(
1152	            current
1153	                .fallback_activations
1154	                .saturating_sub(previous.fallback_activations),
1155	        );
1156	        self.eviction_batches_total.inc_by(
1157	            current
1158	                .eviction_batches
1159	                .saturating_sub(previous.eviction_batches),
1160	        );
1161	        self.evicted_blocks_total.inc_by(
1162	            current
1163	                .evicted_blocks
1164	                .saturating_sub(previous.evicted_blocks),
1165	        );
1166	        self.output_batches_total.inc_by(
1167	            current
1168	                .output_batches
1169	                .saturating_sub(previous.output_batches),
1170	        );
1171	        let requests = current.requests.saturating_sub(previous.requests);
1172	        if requests > 0 {
1173	            let messages = current
1174	                .request_messages
1175	                .saturating_sub(previous.request_messages);
1176	            self.messages_per_request
1177	                .observe(messages as f64 / requests as f64);
1178	        }
1179	        let wait_samples = current
1180	            .mutation_wait_samples
1181	            .saturating_sub(previous.mutation_wait_samples);
1182	        if wait_samples > 0 {
1183	            let wait_ns = current
1184	                .mutation_wait_ns
1185	                .saturating_sub(previous.mutation_wait_ns);
1186	            self.mutation_wait_seconds
1187	                .observe(wait_ns as f64 / wait_samples as f64 / 1_000_000_000.0);
1188	        }
1189	        *previous = current;
1190	    }
1191	}
