1506	mod kv_publisher_registration_tests {
1507	    //! Regression coverage for silently-unregistered KV publisher metrics.
1508	    //!
1509	    //! `engines_dropped_events_total` was once declared with `worker_id` as a
1510	    //! *variable* label. The runtime auto-injects `worker_id` as a *const* label on
1511	    //! every component metric, so the validator rejected the request, the error was
1512	    //! swallowed into an unregistered fallback counter, and the metric never
1513	    //! appeared on `/metrics`. Nothing else observably changed: the fallback
1514	    //! counter still incremented, just nowhere anyone could scrape it.
1515	    //!
1516	    //! These tests build the metric set against a fake hierarchy that injects the
1517	    //! same auto-labels a real `Component` does, then assert each counter reaches
1518	    //! the exposition output. No `DistributedRuntime` and no NATS required.
1519	
1520	    use super::*;
1521	    use dynamo_runtime::MetricsRegistry;
1522	
1523	    /// Stand-in for the DRT → Namespace → Component chain, without a live runtime.
1524	    /// `connection_id` is what drives the auto-injected `worker_id` const label,
1525	    /// so it must be set for these tests to reproduce the original conditions.
1526	    struct FakeHierarchy {
1527	        basename: String,
1528	        parents: Vec<FakeHierarchy>,
1529	        registry: MetricsRegistry,
1530	        connection_id: Option<u64>,
1531	    }
1532	
1533	    impl FakeHierarchy {
1534	        /// Mirror a component-level hierarchy: `["" (drt), namespace, component]`.
1535	        fn component(namespace: &str, component: &str, connection_id: u64) -> Self {
1536	            Self {
1537	                basename: component.to_string(),
1538	                parents: vec![Self::bare(""), Self::bare(namespace)],
1539	                registry: MetricsRegistry::new(),
1540	                connection_id: Some(connection_id),
1541	            }
1542	        }
1543	
1544	        fn bare(name: &str) -> Self {
1545	            Self {
1546	                basename: name.to_string(),
1547	                parents: Vec::new(),
1548	                registry: MetricsRegistry::new(),
1549	                connection_id: None,
1550	            }
1551	        }
1552	
1553	        /// Render what a `/metrics` scrape of this hierarchy would return.
1554	        fn expfmt(&self) -> String {
1555	            self.registry.prometheus_expfmt_combined().unwrap()
1556	        }
1557	    }
1558	
1559	    impl MetricsHierarchy for FakeHierarchy {
1560	        fn basename(&self) -> String {
1561	            self.basename.clone()
1562	        }
1563	
1564	        fn parent_hierarchies(&self) -> Vec<&dyn MetricsHierarchy> {
1565	            self.parents
1566	                .iter()
1567	                .map(|p| p as &dyn MetricsHierarchy)
1568	                .collect()
1569	        }
1570	
1571	        fn get_metrics_registry(&self) -> &MetricsRegistry {
1572	            &self.registry
1573	        }
1574	
1575	        fn connection_id(&self) -> Option<u64> {
1576	            self.connection_id
1577	        }
1578	    }
1579	
1580	    fn exported_name(suffix: &str) -> String {
1581	        format!("{}_{}", name_prefix::COMPONENT, suffix)
1582	    }
1583	
1584	    /// First non-comment sample line for `name`, if the metric was exported at all.
1585	    /// A `# HELP`/`# TYPE` pair without a sample line does not count as exported.
1586	    fn sample_line<'a>(expfmt: &'a str, name: &str) -> Option<&'a str> {
1587	        expfmt
1588	            .lines()
1589	            .filter(|line| !line.starts_with('#'))
1590	            .find(|line| {
1591	                line.strip_prefix(name)
1592	                    .is_some_and(|rest| rest.starts_with('{') || rest.starts_with(' '))
1593	            })
1594	    }
