1596	    #[test]
1597	    fn every_kv_publisher_metric_reaches_the_registry() {
1598	        let hierarchy = FakeHierarchy::component("dynamo", "backend", 0x7f3a1c);
1599	        let metrics = KvPublisherMetrics::build(&hierarchy);
1600	
1601	        // A CounterVec with no observed label values exports no sample lines, so
1602	        // touch each vector once. `engines_dropped_events_total` is deliberately
1603	        // left at zero: a worker that never sees an event_id gap is exactly the
1604	        // state the original bug hid in.
1605	        metrics.increment_zmq_event("received", "stored");
1606	        metrics.increment_zmq_filtered_event("stored", "no_blocks");
1607	        metrics.increment_zmq_conversion_issue("stored", "bad_hash");
1608	        metrics.increment_zmq_suspicious_event("stored", "large_batch");
1609	
1610	        let expfmt = hierarchy.expfmt();
1611	        for suffix in [
1612	            kv_publisher::ENGINES_DROPPED_EVENTS_TOTAL,
1613	            kv_publisher::ZMQ_EVENTS_TOTAL,
1614	            kv_publisher::ZMQ_FILTERED_EVENTS_TOTAL,
1615	            kv_publisher::ZMQ_CONVERSION_ISSUES_TOTAL,
1616	            kv_publisher::ZMQ_SUSPICIOUS_EVENTS_TOTAL,
1617	        ] {
1618	            let name = exported_name(suffix);
1619	            assert!(
1620	                sample_line(&expfmt, &name).is_some(),
1621	                "{name} never reached the metrics registry. Exposition was:\n{expfmt}"
1622	            );
1623	        }
1624	    }
1625	
1626	    #[test]
1627	    fn engines_dropped_counter_is_exported_at_zero_with_auto_labels() {
1628	        let hierarchy = FakeHierarchy::component("dynamo", "backend", 0x7f3a1c);
1629	        let _metrics = KvPublisherMetrics::build(&hierarchy);
1630	
1631	        let expfmt = hierarchy.expfmt();
1632	        let name = exported_name(kv_publisher::ENGINES_DROPPED_EVENTS_TOTAL);
1633	        let line = sample_line(&expfmt, &name)
1634	            .unwrap_or_else(|| panic!("{name} absent from exposition. Exposition was:\n{expfmt}"));
1635	
1636	        // The hierarchy labels a real Component would inject. `worker_id` is the
1637	        // one that collided; it must arrive as a const label, rendered from
1638	        // connection_id as lowercase hex.
1639	        for expected in [
1640	            r#"dynamo_namespace="dynamo""#,
1641	            r#"dynamo_component="backend""#,
1642	            r#"worker_id="7f3a1c""#,
1643	        ] {
1644	            assert!(
1645	                line.contains(expected),
1646	                "expected label {expected} on sample line: {line}"
1647	            );
1648	        }
1649	        assert!(
1650	            line.ends_with(" 0"),
1651	            "counter should be exported at zero before any gap is detected: {line}"
1652	        );
1653	    }
1654	
1655	    #[test]
1656	    fn worker_id_is_rejected_as_a_variable_label() {
1657	        // Pins the mechanism the bug tripped over. If this ever starts returning
1658	        // Ok, the collision is no longer caught at creation time and the guard in
1659	        // `build` above is the only thing standing between a bad label and a
1660	        // silently missing metric.
1661	        let hierarchy = FakeHierarchy::component("dynamo", "backend", 0x7f3a1c);
1662	        let err = hierarchy
1663	            .metrics()
1664	            .create_intcountervec(
1665	                kv_publisher::ENGINES_DROPPED_EVENTS_TOTAL,
1666	                "Total number of raw events dropped by engines",
1667	                &[labels::WORKER_ID],
1668	                &[],
1669	            )
1670	            .expect_err("worker_id must not be usable as a variable label");
1671	        assert!(
1672	            err.to_string()
1673	                .contains("conflicts with auto-injected const label"),
1674	            "unexpected error: {err}"
1675	        );
1676	    }
1677	}
